+  Interfaces, // the LCL widgetset
+  Forms,
+  mormot.tools.logview;
+
+{$R *.res}
+
+begin
+  RequireDerivedFormResource := true;
+  Application.Scaled := true;
+  Application.Initialize;
+  Application.CreateForm(TMainLogView, MainLogView);
+  Application.Run;
+end.
